```c
// logger.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "logger.h"

static log_cb g_cb = NULL;
static void* g_user = NULL;
static int g_running = 0;

void start_log_stream(log_cb cb, void* user) {
    g_cb = cb;
    g_user = user;
    g_running = 1;
    // Simulate logging
    for (int i = 0; i < 10 && g_running; i++) {
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "Log line %d", i);
        if (g_cb) g_cb(buffer, g_user);
        usleep(100000); // 100ms delay
    }
}

void stop_log_stream(void) {
    g_running = 0;
    g_cb = NULL;
    g_user = NULL;
}
```

```go
// logger.go
package main

/*
#cgo LDFLAGS: -lpthread
#include "logger.h"
#include <stdlib.h>
*/
import "C"
import (
	"fmt"
	"runtime"
	"sync"
	"unsafe"
)

type logger struct {
	ch     chan string
	stopCh chan struct{}
	mu     sync.Mutex
}

var globalLogger = &logger{
	ch:     make(chan string, 100),
	stopCh: make(chan struct{}),
}

//export logCallback
func logCallback(line *C.char, user unsafe.Pointer) {
	goStr := C.GoString(line)
	select {
	case globalLogger.ch <- goStr:
	default:
		// Channel full, drop the message or handle backpressure
	}
}

func StartLogger() (<-chan string, error) {
	globalLogger.mu.Lock()
	defer globalLogger.mu.Unlock()

	// Ensure we're locked to an OS thread for CGO callbacks
	runtime.LockOSThread()

	C.start_log_stream((*[0]byte)(C.logCallback), nil)
	return globalLogger.ch, nil
}

func StopLogger() {
	globalLogger.mu.Lock()
	defer globalLogger.mu.Unlock()

	C.stop_log_stream()
	runtime.UnlockOSThread()
}

func main() {
	ch, err := StartLogger()
	if err != nil {
		fmt.Printf("Error starting logger: %v\n", err)
		return
	}

	// Read 3 lines then stop
	for i := 0; i < 3; i++ {
		line := <-ch
		fmt.Printf("Received: %s\n", line)
	}

	StopLogger()
	fmt.Println("Logger stopped")
}
```

